input.command:
for i in $(seq 1 40); do ./executable -m kernel_compile --exit-after-modules 1 -i 100000000 2>&1 | tr -d '\r' > /tmp/gx/one$i.txt; done; python3 - <<'EOF'
import re,glob
for f in sorted(glob.glob('/tmp/gx/one*.txt')):
    lines=open(f).read().split('\n')
    arch=None
    for l in lines:
        if l.startswith('BUILD'):
            arch=l.split('arch/')[1].split('/')[0]
    bad=set()
    for l in lines:
        for m in re.finditer(r'arch/([^/ ]+)/', l):
            if m.group(1)!=arch: bad.add((arch,l))
    if bad:
        for a,l in list(bad)[:5]: print(a,'|',l)
EOF
